package com.citacloud.app.views; import com.citacloud.app.models.*; import com.citacloud.app.security.*; import com.citacloud.app.services.*; import com.vaadin.flow.component.button.Button; import com.vaadin.flow.component.combobox.ComboBox; import com.vaadin.flow.component.grid.Grid; import com.vaadin.flow.component.html.*; import com.vaadin.flow.component.notification.Notification; import com.vaadin.flow.component.orderedlayout.*; import com.vaadin.flow.component.textfield.TextArea; import com.vaadin.flow.component.textfield.TextField; import com.vaadin.flow.component.upload.Upload; import com.vaadin.flow.component.upload.receivers.MemoryBuffer; import com.vaadin.flow.router.*; import jakarta.annotation.security.PermitAll; import java.util.*;
@Route(value="documentos",layout=MainLayout.class) @PageTitle("Documentos | CitaCloud") @PermitAll public class DocumentosView extends VerticalLayout {private final DocumentoService service;private final UUID empresa;private final UUID usuario;private final Grid<Documento> grid=new Grid<>(Documento.class,false);public DocumentosView(DocumentoService s,PacienteService pacientes){service=s;TenantUserDetails u=AuthService.getAuthenticatedUser();empresa=u==null?null:u.getEmpresaId();usuario=u==null?null:u.getUsuarioId();setSizeFull();setPadding(true);Button subir=new Button("Subir documento",e->dialogo(pacientes));add(new HorizontalLayout(new H2("Documentos"),subir),new Paragraph("PDF, PNG o JPG de hasta 10 MB; cada documento queda aislado por empresa."));grid.addColumn(Documento::getNombre).setHeader("NOMBRE");grid.addColumn(d->d.getPaciente()==null?"—":d.getPaciente().getNombreCompleto()).setHeader("PACIENTE");grid.addColumn(Documento::getFecha).setHeader("FECHA");grid.addComponentColumn(d->{Button ver=new Button("Descargar",e->getUI().ifPresent(ui->ui.getPage().open("documentos/"+d.getId(),"_blank")));return ver;}).setHeader("ARCHIVO");grid.setWidthFull();add(grid);cargar();}private void cargar(){grid.setItems(empresa==null?List.of():service.listar(empresa));}private void dialogo(PacienteService pacientes){if(empresa==null)return;com.vaadin.flow.component.dialog.Dialog d=new com.vaadin.flow.component.dialog.Dialog();TextField nombre=new TextField("Nombre");ComboBox<Paciente> paciente=new ComboBox<>("Paciente",pacientes.listarPorEmpresa(empresa));paciente.setItemLabelGenerator(Paciente::getNombreCompleto);TextArea descripcion=new TextArea("Descripción");MemoryBuffer buffer=new MemoryBuffer();Upload upload=new Upload(buffer);upload.setAcceptedFileTypes("application/pdf","image/png","image/jpeg");upload.setMaxFiles(1);upload.setMaxFileSize(10*1024*1024);Button guardar=new Button("Guardar",e->{try(var contenido=buffer.getInputStream()){String archivo=buffer.getFileName();service.subir(empresa,usuario,paciente.getValue()==null?null:paciente.getValue().getId(),nombre.getValue(),descripcion.getValue(),archivo,tipo(archivo),contenido,1);d.close();cargar();Notification.show("Documento guardado correctamente.");}catch(Exception x){Notification.show(x.getMessage());}});d.add(new VerticalLayout(nombre,paciente,descripcion,upload,guardar));d.open();}private String tipo(String archivo){String a=archivo==null?"":archivo.toLowerCase();return a.endsWith(".pdf")?"application/pdf":a.endsWith(".png")?"image/png":"image/jpeg";}}
